#include "karplus_test_access.hpp"
#include "karplus_fixture_reader.hpp"
#include <iostream>
using namespace mfrk::karplus;
int main(int argc,char**argv)try{if(argc!=2)return 2;FixtureReader r(argv[1]);if(r.read<std::array<char,8>>()!=std::array<char,8>{'K','R','P','C','0','0','0','1'}||r.read<std::uint32_t>()!=3)return 2;Tables t;std::uint64_t blocks=0,states=0,buffers=0,seeds=0,raws=0,decoded=0,scaled=0,excites=0;
for(unsigned config=0;config<3;++config){Input in{};in.frequency_hz=F(r.read<std::uint32_t>());in.note=F(r.read<std::uint32_t>());in.words={65535,65535,65535};in.dirty={0,0,0};in.interface_prepare=true;const auto initial=r.read<std::array<std::uint8_t,288>>();const auto initial_memory=r.read<std::array<std::int16_t,8192>>();const auto initial_seed=r.read<std::uint32_t>();const auto cases=r.read<std::uint32_t>();if(!cases||cases>100)return 2;
for(unsigned c=0;c<cases;++c){SharedRandom random{initial_seed};Memory memory{initial_memory};auto expected_memory=initial_memory;auto e=Engine::admitted_zero_arena(t,random,memory);e.bind(0x400020000,8192);e.initialize();for(unsigned i=0;i<288;++i)TestAccess::write(e,i,initial[i]);TestAccess::write(e,0x90,r.read<std::uint32_t>());const auto count=r.read<std::uint32_t>();if(!count||count>100)return 2;
for(unsigned frame=0;frame<count;++frame){const auto after=r.read<std::array<std::uint8_t,288>>();const auto seed=r.read<std::uint32_t>();const auto raw=r.read<std::array<std::int16_t,32>>();const auto dec=r.read<std::array<std::uint32_t,32>>(),scale=r.read<std::array<std::uint32_t,32>>();const auto excitation=r.read<std::array<std::int16_t,32>>();const auto n=r.read<std::uint16_t>();if(n>8192)return 2;int last=-1;for(unsigned i=0;i<n;++i){const auto index=r.read<std::uint16_t>();if(index>=8192||index<=last)return 2;last=index;expected_memory[index]=r.read<std::int16_t>();}std::array<float,32>output{};if(e.try_process(in,output)!=Status::ok){std::cerr<<"status config "<<config<<" case "<<c<<" frame "<<frame<<"\n";return 1;}for(unsigned i=0;i<288;++i){states+=TestAccess::state(e)[i]!=after[i];}for(unsigned i=0;i<8192;++i){buffers+=memory.samples[i]!=expected_memory[i];}seeds+=random.value!=seed;for(unsigned i=0;i<32;++i){raws+=TestAccess::raw(e)[i]!=raw[i];decoded+=std::bit_cast<std::uint32_t>(static_cast<float>(raw[i])*F(939524352))!=dec[i];scaled+=std::bit_cast<std::uint32_t>(output[i])!=scale[i];excites+=TestAccess::excite(e)[i]!=excitation[i];}++blocks;
}}}r.end();std::cout<<"blocks "<<blocks<<" state "<<states<<" buffers "<<buffers<<" seeds "<<seeds<<" raw "<<raws<<" decoded "<<decoded<<" scaled "<<scaled<<" excitation "<<excites<<"\n";return states||buffers||seeds||raws||decoded||scaled||excites?1:0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 2;}
